---@class UserComponent
local UserComponent = Class("UserComponent", ECSComponent)

function UserComponent:__init()
    self.name = "UserComponent"
    ---@type UserDojo
    self.userInfo = UserDojo.New()
end

function UserComponent:__delete()
    self.userInfo = nil
end

function UserComponent:Initial(jsonData)
    if isTable(jsonData) then
        if isSet(jsonData, "userId") then
            self.userInfo.userId = checkNumber(jsonData.userId)
            httpModule.RequestBodyMeta.UserId = checkNumber(jsonData.userId)
            xRecord.setUserPlayer({ userId = tostring(jsonData.userId) })
        end
        if isSet(jsonData, "userName") then
            self.userInfo.userName = checkString(jsonData.userName)
        end
        if isSet(jsonData, "token") then
            self.userInfo.token = checkString(jsonData.token)
        end
        if isSet(jsonData, "lastLoginServerId") then
            self.userInfo.lastLoginServerId = checkNumber(jsonData.lastLoginServerId)
        end
        if isSet(jsonData, "inviteEnable") then
            self.userInfo.inviteEnable = checkNumber(jsonData.inviteEnable)
        end
        if isSet(jsonData, "needCheckIdCard") then
            self.userInfo.needCheckIdCard = checkNumber(jsonData.needCheckIdCard)
        end
        if isSet(jsonData, "playerTestIsClose") then
            self.userInfo.playerTestIsClose = checkNumber(jsonData.needCheckIdCard)
        end
        if isSet(jsonData, "notificationConf") then
            local isOpen = CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 38).num
            if checkInt(isOpen) ~= 1 then
                self.userInfo.notificationConf = checkTable(jsonData.notificationConf)
                ---@type SDKService
                local SDKService = import('Game.Entry.SDKService')
                local sdkService = SDKService:GetInstance()
                local TpnsSdk = sdkService:GetThirdSDK("TpnsSdk")
                if isNotNull(TpnsSdk) then
                    TpnsSdk:OpenNotice()
                end
            end
        end
        if isSet(jsonData, "servers") then
            self.userInfo.servers = {}
            for i, jsonServer in pairs(jsonData.servers) do
                ---@type ServerDojo
                local server = ServerDojo.New()
                server:Fill(jsonServer)
                table.insert(self.userInfo.servers, server)
            end
            table.sort(self.userInfo.servers, function(a, b)
                return checkInt(a.serverId) > checkInt(b.serverId)
            end)
        end
        if isSet(jsonData, "cuurentServerId") then
            self.userInfo.cuurentServerId = checkNumber(jsonData.cuurentServerId)
            local HttpModule = CS.Engine.Http.HttpModule
            HttpModule.RequestBodyMeta.serverId = tostring(jsonData.cuurentServerId)
            self:SetRequestBodyMetaServerAreaId()
            xRecord.setUserPlayer({ serverId = tostring(jsonData.cuurentServerId) })
        end
        if isSet(jsonData, "serverList") then
            self.userInfo.serverList = {}
            for i, jsonServer in pairs(jsonData.serverList) do
                ---@type ServerDojo
                local server = ServerDojo.New()
                server:Fill(jsonServer)
                table.insert(self.userInfo.serverList, server)
            end

            table.sort(self.userInfo.serverList, function(a, b)
                if a.sortIndex == b.sortIndex then
                    return checkInt(a.serverId) > checkInt(b.serverId)
                end
                return a.sortIndex > b.sortIndex
            end)
        end
        if isSet(jsonData, "country_code") then
            self.userInfo.countryCode = checkString(jsonData.country_code)
        end
        if isSet(jsonData, "serverId") then
            self.userInfo.serverId = checkNumber(jsonData.serverId)
            xRecord.setUserPlayer({ serverId = tostring(jsonData.serverId) })
        else
            local lastLoginServerId = checkNumber(jsonData.lastLoginServerId)
            if lastLoginServerId > 0 then
                local dojo = self:GetServerById(lastLoginServerId)
                if dojo then
                    self.userInfo.serverId = checkNumber(dojo.serverId)
                    xRecord.setUserPlayer({ serverId = tostring(dojo.serverId) })
                end
            end
        end
        if isSet(jsonData, "isID") then
            self.userInfo.isId = checkNumber(jsonData.isID)
        end
        if isSet(jsonData, "isPrePlayOpened") then
            self.userInfo.isPrePlayOpened = checkNumber(jsonData.isPrePlayOpened)
        end
        if isSet(jsonData, "prePlayerTimestamp") then
            self.userInfo.prePlayerTimestamp = checkNumber(jsonData.prePlayerTimestamp)
        end
        if isSet(jsonData, "openDownloadWaitShare") then
            self.userInfo.openDownloadWaitShare = checkNumber(jsonData.openDownloadWaitShare)
        end

        if isSet(jsonData, "phone") then
            self.userInfo.phone = checkString(jsonData.phone)
        end
        if isSet(jsonData, "email") then
            self.userInfo.email = checkString(jsonData.email)
        end
        if isSet(jsonData, "is_guest") then
            self.userInfo.isGuest = checkNumber(jsonData.is_guest)
            if KTool.UNITY_EDITOR() then
                self.userInfo.isGuest = 1
            end
        else
            if isSet(jsonData, "userId") then

            end
        end
        if isSet(jsonData, "bindTerminalRewards") then
            self.userInfo.bindTerminalRewards = checkInt(jsonData.bindTerminalRewards)
        end
    end
end

---GetServerById
---得到上次登录的服务器信息
---@param serverId number
---@return ServerDojo
function UserComponent:GetServerById(serverId)
    local dojo
    for _, v in pairs(self.userInfo.servers) do
        if checkNumber(v.serverId) == checkNumber(serverId) then
            dojo = v
            break
        end
    end

    return dojo
end

function UserComponent:GetServerListById(serverId)
    local dojo
    for _, v in pairs(self.userInfo.serverList) do
        if checkNumber(v.serverId) == checkNumber(serverId) then
            dojo = v
            break
        end
    end
    return dojo
end

function UserComponent:GetNewServerByServerList()
    local dojos = {}

    for _, v in pairs(self.userInfo.serverList) do
        if checkNumber(v.isNew) == 1 then
            dojos[#dojos + 1] = v
        end
    end
    if #dojos < 1 then
        return self.userInfo.serverList[#self.userInfo.serverList]
    end
    if dojos then
        math.randomseed(os.time())
        local index = math.random(1, #dojos)
        return dojos[index]
    end
end

function UserComponent:GetRealAuthenticationInfo()
    return self.userInfo.isId
end

---UpdateSDKInfo
---更新sdk参数
---@param jsonData table
---@param isUnResetUserId boolean @ 是否不重置 userId
function UserComponent:UpdateSDKInfo(jsonData, isUnResetUserId)
    if not isUnResetUserId then
        self.userInfo.userId = nil
    end
    if isSet(jsonData, "idNo") then
        self.userInfo.idNo = checkString(jsonData.idNo)
    end
    if isSet(jsonData, "timestamp") then
        self.userInfo.timestamp = checkNumber(jsonData.timestamp)
    end
    if isSet(jsonData, "openId") then
        self.userInfo.openId = tostring(jsonData.openId)
        xRecord.setUserPlayer({ openId = tostring(jsonData.openId) })
    end
    if isSet(jsonData, "sign") then
        self.userInfo.sdkSign = tostring(jsonData.sign)
    end
    if isSet(jsonData, "is_guest") then
        self.userInfo.isGuest = checkNumber(jsonData.is_guest)
        Events.Broadcast("ACCOUNT_REFRESH")
        if KTool.UNITY_EDITOR() then
            self.userInfo.isGuest = 1
        end
    else
        if KTool.UNITY_EDITOR() then
            self.userInfo.isGuest = 1
        end
    end
    if isSet(jsonData, "has_realauth") then
        self.userInfo.hasRealAuth = checkNumber(jsonData.has_realauth)
    end
    -- 增加sdk
    if isSet(jsonData, "access_token") then
        self.userInfo.access_token = checkString(jsonData.access_token)
        httpModule.RequestBodyMeta.AccessToken = checkString(jsonData.access_token)
    end
    -- 增加sdk
    if isSet(jsonData, "accesstoken") then
        self.userInfo.access_token = checkString(jsonData.accesstoken)
        httpModule.RequestBodyMeta.AccessToken = checkString(jsonData.accesstoken)
    end

    -- 增加emulatorName 
    if isSet(jsonData, "emulatorName") then
        self.userInfo.app_id = checkString(jsonData.emulatorName)
        httpModule.RequestBodyMeta.EmulatorName = checkString(jsonData.emulatorName)
    end

    -- 增加sdk
    if isSet(jsonData, "app_id") then
        self.userInfo.app_id = checkString(jsonData.app_id)
        httpModule.RequestBodyMeta.AppId = checkString(jsonData.app_id)
    end

    if isSet(jsonData, "serverId") then
        self.userInfo.serverId = checkNumber(jsonData.serverId)
        local HttpModule = CS.Engine.Http.HttpModule
        HttpModule.RequestBodyMeta.serverId = tostring(jsonData.serverId)
        self:SetRequestBodyMetaServerAreaId()
        xRecord.setUserPlayer({ serverId = tostring(jsonData.serverId) })
    end
    if isSet(jsonData, "isGameCenter") then
        self.userInfo.isGameCenter = checkInt(jsonData.isGameCenter)
    end
end

function UserComponent:SetRequestBodyMetaServerAreaId()
    local HttpModule = CS.Engine.Http.HttpModule
    local serverDojo = self:GetServerListById(HttpModule.RequestBodyMeta.serverId)  
    if isNotNull(serverDojo) then
        local areaId = checkInt(serverDojo.areaId)
        if areaId > 0 then
            local RequestBodyMeta = HttpModule.RequestBodyMeta:GetType()
            if isNotNull(RequestBodyMeta:GetProperty("ServerAreaId")) then
                HttpModule.RequestBodyMeta.ServerAreaId = areaId
            end        
        end
    end
end
function UserComponent:SetSumPayCumulative(sumPayCumulative)
    if self.userInfo then
        self.userInfo.sumPayCumulative = sumPayCumulative
    end
end
function UserComponent:GetSumPayCumulative()
    if self.userInfo then
        return self.userInfo.sumPayCumulative
    end
    return 0
end
function UserComponent:GoToQueueDialog(queueNum, callback)
    GameUtils.Request(Interfaces.UserCheckQueue, { queueNum = queueNum }, function(request, response)
        if tonumber(response.errCode) == 0 then
            local playerNum = checkInt(response.data.result)
            if playerNum <= 0 then
                if callback then
                    callback()
                end
            else
                cs_coroutine.start(function()
                    local queueDialog = GameUtils.LoadBundleAsyncById(Constants.UIModulePrefabsIds.LoginQueueDialog, UIModule.RootCanvas.gameObject, false)
                    local lbComp = KTool.GetComponent(queueDialog, typeof(LuaBehaviour))
                    ---@type LoginQueueWaitDialog
                    local prefabLEnv = not isNull(lbComp) and lbComp.Env or nil
                    if not isNull(prefabLEnv) then
                        prefabLEnv:SetCallBack(callback)
                        prefabLEnv:SetQueueNum(queueNum)
                        prefabLEnv:SetPlayerNum(playerNum)
                    end
                end)
            end
        end
    end)
end

return UserComponent